reg91=0;reg92=0;reg93=0;reg94=0;reg95=0;reg96=0;reg97=0; 
reg98=0;reg99=0; 
loop(4096,exec3( assign(megabuf(lc),0) , assign(gmegabuf(lc),0) , assign(lc,lc+1)));

hp=p/3

code.perFrame:
//preset specific 0-10, 30-40, 70-100;
reg01=p3*.5; reg08=reg08+(b2+loud)*add*20*0;
//feedbackstuff 10-20;
ltime=gettime(time);time=gettime(0);fps=1/ltime;add=1/fps;
reg10=add; 

resize=1-equal(ww,w)*equal(hh,h);ww=w;hh=h;
reg14=resize; 
//vollumedetection
val=100;lp=20;	ilp=1/lp;assign(megabuf(1000),0);lc=0;
fc1=(fc1+1)%val;fc2=(fc1+1)%val;
loop(lp,assign( megabuf(1000),megabuf(1000)+getosc(lc*ilp,0,0))+assign(lc,lc+1));
get=abs(megabuf(1000)*ilp);assign( megabuf(fc1),get);
osctot=osctot+megabuf(fc1)-megabuf(fc2);oscvol=max(0,osctot/val);spec=getspec(.1,.1,0);assign( megabuf(fc1+2000),spec);specavg=max(0,specavg+megabuf(fc1+2000)-megabuf(fc2+2000))-below(getspec(.1,0,0),.1)*.01;specvol=max(0,specavg/val);loudness=(oscvol+specvol)/2;
b1=(b1*.85+bt1);b2=(b2*.85+bt2);b3=(b3*.85+bt3);bt1=0;bt2=0;bt3=0;loud=loudness;
reg15=oscvol; reg16=specvol; reg17=loudness;
reg18=b1;reg19=b2; reg20=b3; 

//ssc&bm rotation and movement 40-60
speedadd=-sl1;
reg35=speedadd;
cammov=max(0,(b3*.5+loud+speedadd));
;reg30=cammov;;


//control;
xax=getkbmouse(1);reg80=xax;
yax=getkbmouse(2);reg81=yax;
xaxin=max(min(xax,1),-1);reg82=xaxin;
yaxin=max(min(yax,1),-1);reg83=yaxin;
inb=below(abs(xax),1)*below(yax,1);reg85=inb;
rc=getkbmouse(3);lc=getkbmouse(4);
click=bor(rc,lc);
shift=getkbmouse(16);
ctrl=getkbmouse(17);
pgup=getkbmouse(33);
pgdown=getkbmouse(34);
lmc=mc;
mc=shift;
control=if(mc*(1-lmc),1-control,control);
reg90=control;
slider1=below(xax,.95)*above(xax,.85)*above(yax,-.5)*below(yax,.5);
slider2=above(xax,-.95)*below(xax,-.85)*above(yax,-.5)*below(yax,.5);
sl1=if(click*slider1*control,yax,sl1);
sl2=if(click*slider2*control,yax,sl2);
reg91=slider1;
reg92=sl1;
reg93=slider2;
reg94=sl2;

asp=w/h;
xs=reg50;
xc=reg51;
ys=reg52;
yc=reg53;
zs=reg54;
zc=reg55;

ox=0;oy=0;oz=.1;

ox2=ox*zc-oy*zs;
oy2=ox*zs+oy*zc;
ox=ox2*yc+oz*ys;
oz2=-ox2*ys+oz*yc;
oy=oy2*xc-oz2*xs;
oz=oy2*xs+oz2*xc;
t=reg00*3

code.perPoint:
x1=x*asp;y1=y;z1=1;
x2=x1*zc+y1*zs;y2=y1*zc-x1*zs;x3=z1*ys-x2*yc;z2=z1*yc+x2*ys;y3=y2*xc+z2*xs;z3=y2*xs-z2*xc;

k1=(abs(x3+oy));
k2=(abs(y3+ox));
k3=(abs(z3+oz));
k=max(k1,k2);
ix=x3/k+ox;
iy=y3/k+oy;
iz=z3/k+oz;
x=(asin(sin(atan2(ix,(iy)))));
y=(iz+t);
alpha=k-.3

code.perFrame:
dst=1;
detail=1.5-reg94*5;
n=max((w+h)*detail,500);
reg97=h/w;reg98=n;
spd=spd*.99;;
bb=bb*.9+b*.1;
t=t-(reg30*reg10*8+bb*.1)*sb2*.8;reg00=t;
spd2=spd2*.99;;
tt=tt+spd2*.3;
rx=sin(tt);ry=cos(tt);rz=sin(tt);
reg50=sin(rx);reg51=cos(rx);reg52=sin(ry);reg53=cos(ry);reg54=sin(rz);reg55=cos(rz);

m1=p2*(n/26)*1.5;reg20=m1;
m2=p2*(n/20)*.8;
lnz=max(min((w+h)*.008,6),4);

mm1=1;im1=1/m;
mm3=1;im2=2/m;

code.perPoint:
r=i*m1;d=max(sin(i*20)*.5,.25);r2=i*m2;
y1=cos(ceil(r))*d;
x1=sin(ceil(r2))*d;
z1=-atan(tan(i*4-2-t))*7;
y2=y1*reg51-z1*reg50;z2=y1*reg50+z1*reg51;x2=z2*reg52+x1*reg53;z3=z2*reg53-x1*reg52;x3=x2*reg55-y2*reg54;y3=y2*reg55+x2*reg54;
z4=1/(1+z3);
x=x3*z4*reg97;
y=y3*z4;
c=(1-z3*.2)*below(z3,4.5)*above(z3,-.5);
red=c;
blue=c;green=c;
linesize=z4*5-.5;
